'use client';
import { useState } from 'react';
import { LayoutDashboard, Package, ShoppingCart, Plus, Pencil, Trash2, CheckCircle2, Clock3, Truck } from 'lucide-react';

const initialProducts=[
 {id:1,name:"Essential Black Tee",price:799,stock:42,status:"Active"},
 {id:2,name:"Classic White Tee",price:699,stock:31,status:"Active"},
 {id:3,name:"Oversized Sand Tee",price:899,stock:18,status:"Active"},
 {id:4,name:"Minimal Grey Tee",price:749,stock:0,status:"Out of stock"}
];
const orders=[
 {id:"#TH-1048",customer:"Rahim Ahmed",product:"Essential Black Tee",size:"L",qty:2,total:1598,status:"Processing"},
 {id:"#TH-1047",customer:"Nusrat Jahan",product:"Classic White Tee",size:"M",qty:1,total:699,status:"Pending"},
 {id:"#TH-1046",customer:"Sakib Hasan",product:"Oversized Sand Tee",size:"XL",qty:1,total:899,status:"Shipped"},
 {id:"#TH-1045",customer:"Mim Akter",product:"Minimal Grey Tee",size:"S",qty:2,total:1498,status:"Delivered"}
];

export default function Admin(){
 const [tab,setTab]=useState<'dashboard'|'products'|'orders'>('dashboard');
 const [products,setProducts]=useState(initialProducts);
 const [orderList,setOrderList]=useState(orders);
 const nav=[['dashboard','Dashboard',LayoutDashboard],['products','Products',Package],['orders','Orders',ShoppingCart]] as const;
 const del=(id:number)=>setProducts(products.filter(p=>p.id!==id));
 const status=(s:string)=>s==='Delivered'?<span className="flex items-center gap-1 text-xs font-bold text-green-700"><CheckCircle2 size={14}/>Delivered</span>:s==='Shipped'?<span className="flex items-center gap-1 text-xs font-bold text-blue-700"><Truck size={14}/>Shipped</span>:<span className="flex items-center gap-1 text-xs font-bold text-orange-700"><Clock3 size={14}/>{s}</span>;
 return <div className="min-h-screen bg-[#f5f5f3]">
  <aside className="fixed hidden h-screen w-60 border-r border-black/10 bg-white p-5 md:block">
   <div className="mb-12 px-2 text-lg font-black tracking-[.2em]">THREAD</div>
   <div className="space-y-1">{nav.map(([key,label,Icon])=><button key={key} onClick={()=>setTab(key)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold ${tab===key?'bg-black text-white':'text-black/60 hover:bg-black/5'}`}><Icon size={18}/>{label}</button>)}</div>
   <div className="absolute bottom-5 left-5 right-5 rounded-xl bg-black/[.04] p-3 text-xs text-black/50">Admin Panel<br/><b className="text-black">admin@thread.store</b></div>
  </aside>
  <main className="md:ml-60">
   <header className="flex items-center justify-between border-b border-black/10 bg-white px-5 py-4 md:px-8">
    <div><p className="text-xs text-black/40">Admin</p><h1 className="text-xl font-bold capitalize">{tab}</h1></div>
    <button className="rounded-full border border-black px-4 py-2 text-xs font-bold">Logout</button>
   </header>
   <div className="mx-auto max-w-6xl p-5 md:p-8">
    {tab==='dashboard'&&<><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
      {[['Total Products',products.length],['Total Orders',orders.length],['Pending Orders',orderList.filter(o=>o.status==='Pending').length],['Processing',orderList.filter(o=>o.status==='Processing').length]].map(x=><div className="rounded-2xl bg-white p-5 shadow-sm" key={x[0]}><p className="text-sm text-black/50">{x[0]}</p><p className="mt-2 text-3xl font-black">{x[1]}</p></div>)}
    </div><div className="mt-8 rounded-2xl bg-white p-5 shadow-sm"><div className="mb-5 flex items-center justify-between"><h2 className="font-bold">Recent Orders</h2><button onClick={()=>setTab('orders')} className="text-xs font-bold underline">View all</button></div><OrdersTable orders={orderList} setOrders={setOrderList}/></div></>}
    {tab==='orders'&&<div className="rounded-2xl bg-white p-5 shadow-sm"><div className="mb-5"><h2 className="text-xl font-bold">Customer Orders</h2><p className="text-sm text-black/45">Process and update order status.</p></div><OrdersTable orders={orderList} setOrders={setOrderList}/></div>}
    {tab==='products'&&<div className="rounded-2xl bg-white p-5 shadow-sm"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-xl font-bold">Products</h2><p className="text-sm text-black/45">Add, edit or delete T-shirts.</p></div><button className="flex items-center gap-2 rounded-xl bg-black px-4 py-2.5 text-sm font-bold text-white"><Plus size={17}/> Add product</button></div><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead><tr className="border-b text-xs uppercase tracking-wider text-black/40"><th className="pb-3">Product</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody>{products.map(p=><tr className="border-b last:border-0" key={p.id}><td className="py-4 font-semibold">{p.name}</td><td>৳{p.price}</td><td>{p.stock}</td><td><span className={`rounded-full px-2 py-1 text-xs font-bold ${p.stock?'bg-green-100 text-green-700':'bg-red-100 text-red-700'}`}>{p.status}</span></td><td><div className="flex gap-2"><button className="rounded-lg border p-2"><Pencil size={15}/></button><button onClick={()=>del(p.id)} className="rounded-lg border p-2 text-red-600"><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div></div>}
   </div>
  </main>
 </div>
}
function OrdersTable({orders,setOrders}:{orders:any[],setOrders:React.Dispatch<React.SetStateAction<any[]>>}){
 return <div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead><tr className="border-b text-xs uppercase tracking-wider text-black/40"><th className="pb-3">Order</th><th>Customer</th><th>Product</th><th>Size</th><th>Total</th><th>Status</th></tr></thead><tbody>{orders.map(o=><tr className="border-b last:border-0" key={o.id}><td className="py-4 font-bold">{o.id}</td><td>{o.customer}</td><td>{o.product} × {o.qty}</td><td>{o.size}</td><td className="font-bold">৳{o.total}</td><td><select value={o.status} onChange={e=>setOrders(prev=>prev.map(x=>x.id===o.id?{...x,status:e.target.value}:x))} className="rounded-lg border bg-white px-2 py-1.5 text-xs"><option>Pending</option><option>Processing</option><option>Shipped</option><option>Delivered</option><option>Cancelled</option></select></td></tr>)}</tbody></table></div>
}